/bin/bash -lc "python3 -c '
from pathlib import Path
import re
root=Path(\".\")
files={\".\".join(p.with_suffix(\"\").parts):p for p in Path(\"MIPStarRE\").rglob(\"*.lean\")}
files[\"MIPStarRE\"]=Path(\"MIPStarRE.lean\")
pat=re.compile(r\""'^import'"\\s+(MIPStarRE(?:\\.[A-Za-z0-9_]+)*)\\s*"'$")
g={m:[] for m in files}
for m,p in files.items():
    for line in p.read_text().splitlines():
        q=pat.match(line)
        if q and q.group(1) in files:
            g[m].append(q.group(1))
def closure(start):
    seen=set(); stack=[start]
    while stack:
        m=stack.pop()
        if m in seen: continue
        seen.add(m); stack.extend(g.get(m,()))
    return seen
checks=[("MIPStarRE",lambda m:m.startswith("MIPStarRE")),("MIPStarRE.QPBT",lambda m:m.startswith("MIPStarRE.QPBT")),("MIPStarRE.Quantum",lambda m:m.startswith("MIPStarRE.Quantum")),("MIPStarRE.QPBT.Combining.Lines",lambda m:m=="MIPStarRE.QPBT.Combining.Lines" or m.startswith("MIPStarRE.QPBT.Combining.Lines.")),("MIPStarRE.QPBT.Games.DistanceTheorems",lambda m:m=="MIPStarRE.QPBT.Games.DistanceTheorems" or m.startswith("MIPStarRE.QPBT.Games.DistanceTheorems."))]
for start,pred in checks:
    c=closure(start); expected={m for m in files if pred(m)}; missing=sorted(expected-c)
    print(f"{start}: closure={len(c)} expected-subtree={len(expected)} missing={len(missing)}")
    for m in missing: print("  MISSING",m)
q=closure("MIPStarRE.Quantum")
leaks=sorted(m for m in q if m.startswith("MIPStarRE.QPBT") or m.startswith("MIPStarRE.LDT"))
print(f"Quantum QPBT/LDT leaks={len(leaks)}")
for m in leaks: print("  LEAK",m)
for target in ["MIPStarRE.QPBT.Games.GroundCompression","MIPStarRE.QPBT.Games.SupportedCompletion","MIPStarRE.QPBT.Combining.Lines.PointwiseDefect","MIPStarRE.QPBT.Games.DistanceTheorems.RoundingTransport","MIPStarRE.Quantum.ControlledUnitary"]:
    print(target, "root", target in closure("MIPStarRE"), "QPBT", target in closure("MIPStarRE.QPBT"), "Quantum", target in q)
'"'"

